import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_storage/firebase_storage.dart';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';
class BannersAdminPage extends StatefulWidget{const BannersAdminPage({super.key});@override State<BannersAdminPage> createState()=>_B();}
class _B extends State<BannersAdminPage>{Future<void> add()async{final title=TextEditingController();final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:88);if(x==null)return;final file=File(x.path);final ref=FirebaseStorage.instance.ref('banners/'+DateTime.now().millisecondsSinceEpoch.toString()+'.jpg');await ref.putFile(file);final url=await ref.getDownloadURL();await FirebaseFirestore.instance.collection('banners').add({'title':title.text.trim(),'imageUrl':url,'active':true,'createdAt':FieldValue.serverTimestamp()});}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Banner & Promo')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add_photo_alternate),label:const Text('Upload Banner')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('banners').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(12),children:s.data!.docs.map((d){final x=d.data();return Card(child:ListTile(leading:x['imageUrl']?.toString().isNotEmpty==true?Image.network(x['imageUrl'],width:70,height:50,fit:BoxFit.cover):const Icon(Icons.image),title:Text(x['title']??'Banner'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Switch(value:x['active']??true,onChanged:(v)=>d.reference.update({'active':v})),IconButton(onPressed:()=>d.reference.delete(),icon:const Icon(Icons.delete_outline))]));}).toList());}));}